    /** Returns the asset slug of the flag the [remarks] of a server point to, or null. */
    fun slugFor(remarks: String): String? {
        if (remarks.isBlank()) return null
        // 1. A flag emoji is two regional indicator symbols.
        var i = 0
        while (i < remarks.length) {
            val cp = remarks.codePointAt(i)
            val next = i + Character.charCount(cp)
            if (cp in 0x1F1E6..0x1F1FF && next < remarks.length) {
                val cp2 = remarks.codePointAt(next)
                if (cp2 in 0x1F1E6..0x1F1FF) {
                    val code = "" + ('A' + (cp - 0x1F1E6)) + ('A' + (cp2 - 0x1F1E6))
                    isoToSlug[code]?.let { return it }
                }
            }
            i = next
        }
        // 2. A country name.
        val lower = remarks.lowercase()
        for ((name, slug) in nameToSlug) {
            val at = lower.indexOf(name)
            if (at < 0) continue
            val before = if (at == 0) ' ' else lower[at - 1]
            val after = if (at + name.length >= lower.length) ' ' else lower[at + name.length]
            if (!before.isLetter() && !after.isLetter()) return slug
        }
        // 3. A two-letter code standing alone, such as "DE" or "US".
        for (token in remarks.split(Regex("[^A-Za-z]+"))) {
            if (token.length == 2 && token == token.uppercase()) isoToSlug[token]?.let { return it }
        }
        return null
    }
}
